"""YAML renderer. Hand-rolled serializer -- standard library only, see CONTRIBUTING.md."""

import json
import math
import re

from plugins import PluginError, Renderer, register

# A plain (unquoted) YAML scalar that cannot be mistaken for anything else:
# starts with a letter or underscore, then letters, digits, underscores,
# hyphens, dots, spaces, or slashes, and does not end in whitespace.
_PLAIN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_./-]*(?: [A-Za-z0-9_./-]+)*$")

# Plain words that YAML 1.1/1.2 parsers would read as bool/null/etc.
_RESERVED = {
    "true", "false", "yes", "no", "on", "off", "y", "n",
    "null", "~", ".inf", "-.inf", ".nan",
}


def _scalar(value) -> str:
    """Serialize a single flat value as a YAML scalar."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        if _PLAIN_RE.match(value) and value.lower() not in _RESERVED:
            return value
        # YAML double-quoted scalars accept JSON string escapes, so json.dumps
        # gives us a correctly quoted and escaped form.
        return json.dumps(value, ensure_ascii=False)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


def _key(key) -> str:
    if not isinstance(key, str):
        raise PluginError(f"yaml needs string keys, got {type(key).__name__}")
    return _scalar(key)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for r in rows:
            if not r:
                lines.append("- {}")
                continue
            first = True
            for k, v in r.items():
                prefix = "- " if first else "  "
                lines.append(f"{prefix}{_key(k)}: {_scalar(v)}")
                first = False
        return "\n".join(lines) + "\n"

