"""YAML renderer. Hand-rolled emitter: the package is standard library only."""

import math

from plugins import PluginError, Renderer, register

# Plain (unquoted) strings that a YAML parser would read as something other
# than a string. Quoting them keeps round-trips faithful.
_RESERVED = {
    "", "~", "null", "Null", "NULL",
    "true", "True", "TRUE", "false", "False", "FALSE",
    "yes", "Yes", "YES", "no", "No", "NO",
    "on", "On", "ON", "off", "Off", "OFF",
    "y", "Y", "n", "N",
    ".nan", ".NaN", ".NAN", ".inf", ".Inf", ".INF",
    "-.inf", "-.Inf", "-.INF", "+.inf", "+.Inf", "+.INF",
}

# Characters that cannot start a plain scalar, or that are ambiguous inside one.
_UNSAFE_LEAD = set("-?:,[]{}#&*!|>'\"%@`")
_UNSAFE_ANY = ("#", ": ", "\t", "\n", "\r")


def _looks_numeric(s: str) -> bool:
    try:
        float(s)
        return True
    except ValueError:
        pass
    stripped = s[1:] if s[:1] in "+-" else s
    lowered = stripped.lower()
    if lowered.startswith(("0x", "0o", "0b")) and len(lowered) > 2:
        return True
    return bool(stripped) and stripped.isdigit()


def _quote(s: str) -> str:
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ord(ch) < 0x20 or ch == "\x7f":
            out.append(f"\\x{ord(ch):02x}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def _string(s: str) -> str:
    if (
        s in _RESERVED
        or s != s.strip()
        or s[0] in _UNSAFE_LEAD
        or s.endswith(":")
        or any(tok in s for tok in _UNSAFE_ANY)
        or _looks_numeric(s)
    ):
        return _quote(s)
    return s


def _scalar(value) -> str:
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        return _string(value)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for r in rows:
            if not r:
                lines.append("- {}")
                continue
            prefix = "- "
            for key, value in r.items():
                if not isinstance(key, str):
                    raise PluginError("yaml needs string keys")
                lines.append(f"{prefix}{_string(key)}: {_scalar(value)}")
                prefix = "  "
        return "\n".join(lines) + "\n"

